<script>
(function () {
  function init() {
    try {
      var btn = document.getElementById('tl-menu-btn');
      var nav = document.getElementById('tl-nav');
      if (!btn || !nav) return;

      var links = nav.querySelectorAll('a[href^="#"]');
      for (var i = 0; i < links.length; i++) {
        var a = links[i];
        var id = a.getAttribute('href').slice(1);
        if (document.getElementById(id)) continue;
        var alts = (a.getAttribute('data-alt') || '').split(',');
        var found = null;
        for (var j = 0; j < alts.length; j++) {
          var alt = alts[j].trim();
          if (alt && document.getElementById(alt)) { found = alt; break; }
        }
        if (found) { a.setAttribute('href', '#' + found); }
        else { a.hidden = true; }
      }

      function setOpen(open) {
        nav.classList.toggle('tl-open', open);
        btn.setAttribute('aria-expanded', open ? 'true' : 'false');
        btn.textContent = open ? 'Close' : 'Menu';
      }
      btn.addEventListener('click', function () {
        setOpen(!nav.classList.contains('tl-open'));
      });
      nav.addEventListener('click', function (e) {
        if (e.target && e.target.closest && e.target.closest('a')) setOpen(false);
      });
      document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape') setOpen(false);
      });
    } catch (err) { /* nav stays usable without the toggle */ }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
</script>
