(function () {
  try {
    var root = document.getElementById('shop');
    if (!root) return;
    var cards = root.querySelectorAll('.tl-card');
    var tabs = root.querySelectorAll('.tl-tab');
    var sizeSel = document.getElementById('tl-size');
    var priceSel = document.getElementById('tl-price');
    var status = document.getElementById('tl-status');
    var empty = document.getElementById('tl-empty');
    var resets = root.querySelectorAll('.tl-reset');
    var cat = 'all';

    function orderHref(card, size) {
      var msg = 'Hi Thread & Loom, I would like to order: ' + card.getAttribute('data-name') +
        ' (Rs ' + card.getAttribute('data-price-text') + ')' +
        (size && size !== 'all' && size !== 'FREE' ? ', size ' + size : '') + '.';
      return 'https://wa.me/910000011111?text=' + encodeURIComponent(msg);
    }

    function apply() {
      var size = sizeSel.value;
      var range = priceSel.value;
      var min = 0, max = Infinity;
      if (range !== 'all') {
        var parts = range.split('-');
        min = parseInt(parts[0], 10);
        max = parseInt(parts[1], 10);
      }
      var shown = 0;
      for (var i = 0; i < cards.length; i++) {
        var c = cards[i];
        var price = parseInt(c.getAttribute('data-price'), 10);
        var sizes = c.getAttribute('data-sizes').split(' ');
        var ok = (cat === 'all' || c.getAttribute('data-cat') === cat) &&
                 (size === 'all' || sizes.indexOf(size) !== -1) &&
                 (price >= min && price <= max);
        c.hidden = !ok;
        if (ok) shown++;
        var link = c.querySelector('.tl-order');
        if (link) link.setAttribute('href', orderHref(c, size));
      }
      status.textContent = 'Showing ' + shown + ' of ' + cards.length + ' products';
      empty.hidden = shown !== 0;
    }

    for (var t = 0; t < tabs.length; t++) {
      tabs[t].addEventListener('click', function () {
        cat = this.getAttribute('data-cat');
        for (var k = 0; k < tabs.length; k++) {
          tabs[k].setAttribute('aria-pressed', tabs[k] === this ? 'true' : 'false');
        }
        apply();
      });
    }
    sizeSel.addEventListener('change', apply);
    priceSel.addEventListener('change', apply);
    for (var r = 0; r < resets.length; r++) {
      resets[r].addEventListener('click', function () {
        cat = 'all';
        sizeSel.value = 'all';
        priceSel.value = 'all';
        for (var k = 0; k < tabs.length; k++) {
          tabs[k].setAttribute('aria-pressed', tabs[k].getAttribute('data-cat') === 'all' ? 'true' : 'false');
        }
        apply();
      });
    }
    apply();
  } catch (err) { /* cards are plain HTML, so the catalogue stays readable without filters */ }
})();
</script>
